<x-layouts.app><h1>{{ $device->exists ? 'Edit' : 'Add' }} Device</h1><form class="card" method="POST" action="{{ $device->exists ? route('devices.update',$device) : route('devices.store') }}">@csrf @if($device->exists)@method('PUT')@endif<label>Device name</label><input name="name" value="{{ old('name',$device->name) }}" required><label>Site</label><select name="site_id">@foreach($sites as $site)<option value="{{ $site->id }}" @selected(old('site_id',$device->site_id)==$site->id)>{{ $site->name }}</option>@endforeach</select><label>Device type</label><select name="device_type_id">@foreach($types as $type)<option value="{{ $type->id }}" @selected(old('device_type_id',$device->device_type_id)==$type->id)>{{ $type->name }}</option>@endforeach</select><label>Static IP address</label><input name="management_ip" value="{{ old('management_ip',$device->management_ip) }}" placeholder="192.168.1.10" required><input type="hidden" name="ip_assignment" value="static"><label>MAC address</label><input name="mac_address" value="{{ old('mac_address',$device->mac_address) }}" placeholder="00:11:22:33:44:55" required><label>Default gateway</label><input name="default_gateway" value="{{ old('default_gateway',$device->default_gateway) }}" placeholder="192.168.1.1" required><label>Subnet mask</label><input name="subnet_mask" value="{{ old('subnet_mask',$device->subnet_mask) }}" placeholder="255.255.255.0" required><label>Monitoring profile</label><select name="monitoring_profile_id"><option value="">None</option>@foreach($profiles as $profile)<option value="{{ $profile->id }}" @selected(old('monitoring_profile_id',$device->monitoring_profile_id)==$profile->id)>{{ $profile->name }}</option>@endforeach</select><label>Hostname</label><input name="hostname" value="{{ old('hostname',$device->hostname) }}"><label>Criticality</label><select name="criticality">@foreach(['critical','high','medium','low'] as $value)<option value="{{ $value }}" @selected(old('criticality',$device->criticality ?: 'medium')===$value)>{{ ucfirst($value) }}</option>@endforeach</select><label>Notes</label><textarea name="notes">{{ old('notes',$device->notes) }}</textarea><input type="hidden" name="is_active" value="0"><label><input style="width:auto" type="checkbox" name="is_active" value="1" @checked(old('is_active',$device->is_active ?? true))> Active</label><button class="button">Save device</button></form></x-layouts.app>
